@* Displays a single task card with move buttons *@

<div class="task-card">
    <div class="task-title">@Task.Title</div>
    <div class="task-assignee">@Task.Assignee</div>
    <span class="priority-badge @GetPriorityClass()">@Task.Priority</span>
    <div class="task-due-date">@Task.DueDate.ToString("MMM dd")</div>
    <div class="task-actions">
        @if (ShowMoveLeft)
        {
            <button class="btn-move-left" @onclick="OnMoveLeftClick">Move Left</button>
        }
        @if (ShowMoveRight)
        {
            <button class="btn-move-right" @onclick="OnMoveRightClick">Move Right</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public TaskItem Task { get; set; } = default!;

    [Parameter]
    public bool ShowMoveLeft { get; set; }

    [Parameter]
    public bool ShowMoveRight { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveRight { get; set; }

    private string GetPriorityClass() => Task.Priority switch
    {
        "High" => "priority-high",
        "Medium" => "priority-medium",
        "Low" => "priority-low",
        _ => ""
    };

    private async System.Threading.Tasks.Task OnMoveLeftClick() => await OnMoveLeft.InvokeAsync(Task);
    private async System.Threading.Tasks.Task OnMoveRightClick() => await OnMoveRight.InvokeAsync(Task);
}

@* Inline form to create a new task within a column *@

<div class="add-task-form">
    <input type="text" placeholder="Title" @bind="title" />
    <input type="text" placeholder="Assignee" @bind="assignee" />
    <select @bind="priority">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="dueDate" />
    <div class="form-actions">
        <button class="btn-save" @onclick="Save">Save</button>
        <button class="btn-cancel" @onclick="Cancel">Cancel</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public string Status { get; set; } = default!;

    [Parameter]
    public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnSave { get; set; }

    [Parameter]
    public EventCallback OnCancel { get; set; }

    private string title = "";
    private string assignee = "";
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);

    private async Task Save()
    {
        if (!string.IsNullOrWhiteSpace(title))
        {
            await OnSave.InvokeAsync((title, assignee, priority, dueDate));
            title = "";
            assignee = "";
            priority = "Medium";
            dueDate = DateTime.Today.AddDays(7);
        }
    }

    private async Task Cancel() => await OnCancel.InvokeAsync();
}

@* A single Kanban column showing its tasks and optional add form *@

<div class="board-column">
    <div class="column-header">
        <h3>@Title (@Tasks.Count)</h3>
    </div>
    <div class="column-tasks">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      OnMoveLeft="OnMoveLeft"
                      OnMoveRight="OnMoveRight" />
        }
    </div>
    @if (showForm)
    {
        <AddTaskForm Status="@Status"
                     OnSave="HandleSave"
                     OnCancel="HideForm" />
    }
    else
    {
        <button class="btn-add-task" @onclick="ShowForm">Add Task</button>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public string Title { get; set; } = default!;

    [Parameter, EditorRequired]
    public string Status { get; set; } = default!;

    [Parameter]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public bool ShowMoveLeft { get; set; }

    [Parameter]
    public bool ShowMoveRight { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveRight { get; set; }

    [Parameter]
    public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnTaskCreated { get; set; }

    private bool showForm;

    private void ShowForm() => showForm = true;
    private void HideForm() => showForm = false;

    private async Task HandleSave((string Title, string Assignee, string Priority, DateTime DueDate) data)
    {
        await OnTaskCreated.InvokeAsync(data);
        showForm = false;
    }
}

@* Summary statistics bar for the Kanban board *@

<div class="board-stats">
    <span class="stat-item">Total: @Total</span>
    <span class="stat-item">To Do: @TodoCount</span>
    <span class="stat-item">In Progress: @InProgressCount</span>
    <span class="stat-item">Done: @DoneCount</span>
    <span class="stat-item stat-overdue">Overdue: @OverdueCount</span>
</div>

@code {
    [Parameter] public int Total { get; set; }
    [Parameter] public int TodoCount { get; set; }
    [Parameter] public int InProgressCount { get; set; }
    [Parameter] public int DoneCount { get; set; }
    [Parameter] public int OverdueCount { get; set; }
}

@* Search bar for filtering tasks by title *@

<div class="board-search">
    <input type="text" placeholder="Search tasks..." value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter]
    public string SearchText { get; set; } = "";

    [Parameter]
    public EventCallback<string> SearchTextChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? "";
        await SearchTextChanged.InvokeAsync(value);
    }
}

@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2>Kanban Board</h2>

@if (loading)
{
    <p class="loading-message">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error-message">@errorMessage</p>
}
else
{
    <BoardStats Total="allTasks.Count"
                TodoCount="todoTasks.Count"
                InProgressCount="inProgressTasks.Count"
                DoneCount="doneTasks.Count"
                OverdueCount="overdueTasks.Count" />

    <BoardSearchBar SearchText="@searchText" SearchTextChanged="HandleSearchChanged" />

    <div class="board-columns">
        <BoardColumn Title="To Do"
                     Status="To Do"
                     Tasks="filteredTodo"
                     ShowMoveLeft="false"
                     ShowMoveRight="true"
                     OnMoveRight="MoveToInProgress"
                     OnTaskCreated="args => CreateTask(args, \"To Do\")" />

        <BoardColumn Title="In Progress"
                     Status="In Progress"
                     Tasks="filteredInProgress"
                     ShowMoveLeft="true"
                     ShowMoveRight="true"
                     OnMoveLeft="MoveToTodo"
                     OnMoveRight="MoveToDone"
                     OnTaskCreated="args => CreateTask(args, \"In Progress\")" />

        <BoardColumn Title="Done"
                     Status="Done"
                     Tasks="filteredDone"
                     ShowMoveLeft="true"
                     ShowMoveRight="false"
                     OnMoveLeft="MoveToInProgress2"
                     OnTaskCreated="args => CreateTask(args, \"Done\")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private bool loading = true;
    private string? errorMessage;
    private string searchText = "";

    private List<TaskItem> todoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> inProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> doneTasks => allTasks.Where(t => t.Status == "Done").ToList();
    private int overdueTasks_Count => allTasks.Count(t => t.DueDate < DateTime.Today);
    private List<TaskItem> overdueTasks => allTasks.Where(t => t.DueDate < DateTime.Today).ToList();

    private List<TaskItem> filteredTodo => FilterBySearch(todoTasks);
    private List<TaskItem> filteredInProgress => FilterBySearch(inProgressTasks);
    private List<TaskItem> filteredDone => FilterBySearch(doneTasks);

    private List<TaskItem> FilterBySearch(List<TaskItem> tasks)
    {
        if (string.IsNullOrWhiteSpace(searchText))
            return tasks;
        return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private void HandleSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task MoveToInProgress(TaskItem task)
    {
        await TaskService.UpdateTaskStatusAsync(task.Id, "In Progress");
        allTasks = allTasks.Select(t => t.Id == task.Id ? task with { Status = "In Progress" } : t).ToList();
    }

    private async Task MoveToTodo(TaskItem task)
    {
        await TaskService.UpdateTaskStatusAsync(task.Id, "To Do");
        allTasks = allTasks.Select(t => t.Id == task.Id ? task with { Status = "To Do" } : t).ToList();
    }

    private async Task MoveToDone(TaskItem task)
    {
        await TaskService.UpdateTaskStatusAsync(task.Id, "Done");
        allTasks = allTasks.Select(t => t.Id == task.Id ? task with { Status = "Done" } : t).ToList();
    }

    private async Task MoveToInProgress2(TaskItem task)
    {
        await TaskService.UpdateTaskStatusAsync(task.Id, "In Progress");
        allTasks = allTasks.Select(t => t.Id == task.Id ? task with { Status = "In Progress" } : t).ToList();
    }

    private async Task CreateTask((string Title, string Assignee, string Priority, DateTime DueDate) data, string status)
    {
        var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
        // The service creates with default status; update if needed
        if (newTask.Status != status)
        {
            await TaskService.UpdateTaskStatusAsync(newTask.Id, status);
            newTask = newTask with { Status = status };
        }
        allTasks.Add(newTask);
    }
}

