@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2>Kanban Board</h2>

@if (loading)
{
    <p class="loading-message">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error-message">@errorMessage</p>
}
else
{
    <BoardStats Total="allTasks.Count"
                TodoCount="todoTasks.Count"
                InProgressCount="inProgressTasks.Count"
                DoneCount="doneTasks.Count"
                OverdueCount="overdueCount" />

    <BoardSearchBar SearchText="@searchText" SearchTextChanged="HandleSearchChanged" />

    <div class="board-columns">
        <BoardColumn Title="To Do"
                     Status="To Do"
                     Tasks="filteredTodo"
                     ShowMoveLeft="false"
                     ShowMoveRight="true"
                     OnMoveRight="MoveToInProgress"
                     OnTaskCreated="args => CreateTask(args, &quot;To Do&quot;)" />

        <BoardColumn Title="In Progress"
                     Status="In Progress"
                     Tasks="filteredInProgress"
                     ShowMoveLeft="true"
                     ShowMoveRight="true"
                     OnMoveLeft="MoveToTodo"
                     OnMoveRight="MoveToDone"
                     OnTaskCreated="args => CreateTask(args, &quot;In Progress&quot;)" />

        <BoardColumn Title="Done"
                     Status="Done"
                     Tasks="filteredDone"
                     ShowMoveLeft="true"
                     ShowMoveRight="false"
                     OnMoveLeft="MoveBackToInProgress"
                     OnTaskCreated="args => CreateTask(args, &quot;Done&quot;)" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private bool loading = true;
    private string? errorMessage;
    private string searchText = "";

    private List<TaskItem> todoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> inProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> doneTasks => allTasks.Where(t => t.Status == "Done").ToList();
    private int overdueCount => allTasks.Count(t => t.DueDate < DateTime.Today);

    private List<TaskItem> filteredTodo => FilterBySearch(todoTasks);
    private List<TaskItem> filteredInProgress => FilterBySearch(inProgressTasks);
    private List<TaskItem> filteredDone => FilterBySearch(doneTasks);

    private List<TaskItem> FilterBySearch(List<TaskItem> tasks)
    {
        if (string.IsNullOrWhiteSpace(searchText))
            return tasks;
        return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private void HandleSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task MoveToInProgress(TaskItem task)
    {
        await TaskService.UpdateTaskStatusAsync(task.Id, "In Progress");
        allTasks = allTasks.Select(t => t.Id == task.Id ? task with { Status = "In Progress" } : t).ToList();
    }

    private async Task MoveToTodo(TaskItem task)
    {
        await TaskService.UpdateTaskStatusAsync(task.Id, "To Do");
        allTasks = allTasks.Select(t => t.Id == task.Id ? task with { Status = "To Do" } : t).ToList();
    }

    private async Task MoveToDone(TaskItem task)
    {
        await TaskService.UpdateTaskStatusAsync(task.Id, "Done");
        allTasks = allTasks.Select(t => t.Id == task.Id ? task with { Status = "Done" } : t).ToList();
    }

    private async Task MoveBackToInProgress(TaskItem task)
    {
        await TaskService.UpdateTaskStatusAsync(task.Id, "In Progress");
        allTasks = allTasks.Select(t => t.Id == task.Id ? task with { Status = "In Progress" } : t).ToList();
    }

    private async Task CreateTask((string Title, string Assignee, string Priority, DateTime DueDate) data, string status)
    {
        var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
        if (newTask.Status != status)
        {
            await TaskService.UpdateTaskStatusAsync(newTask.Id, status);
            newTask = newTask with { Status = status };
        }
        allTasks.Add(newTask);
    }
}

