namespace sv_980e12fb0d864fac81bdb978b222f8cb;

public record TaskItem(int Id, string Title, string Assignee, string Priority, DateTime DueDate, string Status);

public interface ITaskService
{
    Task<List<TaskItem>> GetAllTasksAsync();
    Task<TaskItem> CreateTaskAsync(string title, string assignee, string priority, DateTime dueDate);
    Task UpdateTaskStatusAsync(int taskId, string newStatus);
}

.board-stats {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 0.5rem;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.stat-item {
    font-weight: 600;
}

.stat-overdue {
    color: #dc3545;
}

.board-search {
    margin-bottom: 1rem;
}

.board-search input {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
}

.board-columns {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.board-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 0.5rem;
    padding: 1rem;
    min-width: 250px;
}

.column-header h3 {
    margin: 0 0 1rem 0;
    font-size: 1.1rem;
}

.column-tasks {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    margin-bottom: 1rem;
}

.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    padding: 0.75rem;
}

.task-title {
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.task-assignee {
    font-size: 0.875rem;
    color: #6c757d;
    margin-bottom: 0.25rem;
}

.priority-badge {
    display: inline-block;
    padding: 0.125rem 0.5rem;
    border-radius: 0.25rem;
    font-size: 0.75rem;
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.priority-high {
    background: #dc3545;
    color: #fff;
}

.priority-medium {
    background: #ffc107;
    color: #212529;
}

.priority-low {
    background: #28a745;
    color: #fff;
}

.task-due-date {
    font-size: 0.875rem;
    color: #495057;
    margin-bottom: 0.5rem;
}

.task-actions {
    display: flex;
    gap: 0.5rem;
}

.btn-move-left,
.btn-move-right {
    font-size: 0.75rem;
    padding: 0.25rem 0.5rem;
    border: 1px solid #6c757d;
    border-radius: 0.25rem;
    background: #fff;
    cursor: pointer;
}

.btn-move-left:hover,
.btn-move-right:hover {
    background: #e9ecef;
}

.btn-add-task {
    width: 100%;
    padding: 0.5rem;
    border: 1px dashed #6c757d;
    border-radius: 0.375rem;
    background: transparent;
    cursor: pointer;
    color: #6c757d;
}

.btn-add-task:hover {
    background: #e9ecef;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.75rem;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
}

.add-task-form input,
.add-task-form select {
    padding: 0.375rem;
    border: 1px solid #ced4da;
    border-radius: 0.25rem;
}

.form-actions {
    display: flex;
    gap: 0.5rem;
}

.btn-save {
    padding: 0.375rem 0.75rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 0.25rem;
    cursor: pointer;
}

.btn-cancel {
    padding: 0.375rem 0.75rem;
    background: #6c757d;
    color: #fff;
    border: none;
    border-radius: 0.25rem;
    cursor: pointer;
}

.loading-message {
    color: #6c757d;
    font-style: italic;
}

.error-message {
    color: #dc3545;
    font-weight: 600;
}

